from pathlib import Path
import json,subprocess,shlex
O=Path('evidence/2026-11-03/runtime-controlled-six');run=json.load(open(O/'run.json'))['validationRunId'];ssh=['ssh','-o','BatchMode=yes','-o','ConnectTimeout=6','-o','StrictHostKeyChecking=yes','-o','HostName=192.168.64.11','-o','HostKeyAlias=192.168.1.58','zhang@192.168.1.58']
script=r'''const fs=require('fs'),cp=require('child_process'),r=process.argv[1],k='/tmp/runtime-six-credentials-'+r+'/executor.kubeconfig';const checks=[['create','pods','devsecops-execution',true],['get','pods','devsecops-execution',true],['create','pods/exec','devsecops-execution',true],['delete','pods','devsecops-execution',true],['get','lease/platform-heavy','data-infra',true],['get','secrets','petclinic',false],['list','secrets','devsecops-execution',false],['create','pods','petclinic',false],['patch','deployments','petclinic',false],['create','roles','devsecops-execution',false],['delete','namespaces','default',false],['impersonate','users','default',false]];const rows=checks.map(([verb,res,ns,expected])=>{const p=cp.spawnSync('kubectl',['--kubeconfig',k,'auth','can-i',verb,res,'-n',ns],{encoding:'utf8',timeout:15000});const allowed=p.stdout.trim()==='yes';if(allowed!==expected)throw Error('RBAC mismatch '+verb+' '+res);return {verb,resource:res,namespace:ns,expected,observed:p.stdout.trim(),exitStatus:p.status};});console.log(JSON.stringify({checks:rows,allMatched:true}));'''
p=subprocess.run(ssh+['sudo -n kubectl exec -n ns-devops deploy/jenkins -c jenkins -- node -e '+shlex.quote(script)+' '+shlex.quote(run)],capture_output=True,text=True,timeout=60);assert p.returncode==0,p.stderr[-400:];(O/'minimum-rbac-real-checks.json').write_text(json.dumps(json.loads(p.stdout),indent=2)+'\n');print('MINIMUM_RBAC_REAL_CHECKS_12_MATCH')
